use std::io;
use std::time::{Duration, Instant};

use crossterm::{
    event::{self, Event, KeyCode},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use ratatui::{
    backend::CrosstermBackend,
    layout::{Alignment, Rect},
    style::{Color, Modifier, Style},
    text::{Line, Span},
    widgets::{Block, Borders, Paragraph},
    Terminal,
};

const HELLO: &str = "Hello, World!";
const TICK: Duration = Duration::from_millis(50);

fn main() -> io::Result<()> {
    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let result = run(&mut terminal);

    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;

    result
}

fn run(terminal: &mut Terminal<CrosstermBackend<io::Stdout>>) -> io::Result<()> {
    let start = Instant::now();

    loop {
        let elapsed = start.elapsed().as_millis() as f64;

        if event::poll(Duration::ZERO)? {
            if let Event::Key(key) = event::read()? {
                if matches!(key.code, KeyCode::Char('q') | KeyCode::Esc) {
                    break;
                }
            }
        }

        terminal.draw(|frame| {
            let area = frame.area();
            let t = elapsed / 1000.0;

            // Bounce the text around the screen
            let text_width = HELLO.len() as u16 + 4;
            let text_height = 3u16;
            let max_x = area.width.saturating_sub(text_width);
            let max_y = area.height.saturating_sub(text_height);

            let x = ((t * 0.7).sin() * 0.5 + 0.5) * max_x as f64;
            let y = ((t * 0.5).cos() * 0.5 + 0.5) * max_y as f64;

            // Cycle through colors based on time
            let hue = ((t * 60.0) as u32) % 360;
            let color = hue_to_color(hue);

            let rect = Rect {
                x: x as u16,
                y: y as u16,
                width: text_width,
                height: text_height,
            };

            // Animate individual characters with a wave effect
            let chars: Vec<Span> = HELLO
                .chars()
                .enumerate()
                .map(|(i, c)| {
                    let phase = t * 4.0 - i as f64 * 0.4;
                    let bright = (phase.sin() * 0.5 + 0.5) > 0.5;
                    let style = if bright {
                        Style::default().fg(color).add_modifier(Modifier::BOLD)
                    } else {
                        Style::default().fg(color)
                    };
                    Span::styled(c.to_string(), style)
                })
                .collect();

            let block = Block::default()
                .borders(Borders::ALL)
                .border_style(Style::default().fg(color));

            let paragraph = Paragraph::new(Line::from(chars))
                .block(block)
                .alignment(Alignment::Center);

            frame.render_widget(paragraph, rect);

            // Quit hint at bottom
            let hint = Paragraph::new("press q to quit")
                .style(Style::default().fg(Color::DarkGray))
                .alignment(Alignment::Center);
            let hint_rect = Rect {
                x: 0,
                y: area.height.saturating_sub(1),
                width: area.width,
                height: 1,
            };
            frame.render_widget(hint, hint_rect);
        })?;

        std::thread::sleep(TICK);
    }

    Ok(())
}

fn hue_to_color(hue: u32) -> Color {
    let h = hue % 360;
    let (r, g, b) = match h {
        0..=59 => {
            let f = h as f64 / 60.0;
            (255, (f * 255.0) as u8, 0)
        }
        60..=119 => {
            let f = (h - 60) as f64 / 60.0;
            ((255.0 * (1.0 - f)) as u8, 255, 0)
        }
        120..=179 => {
            let f = (h - 120) as f64 / 60.0;
            (0, 255, (f * 255.0) as u8)
        }
        180..=239 => {
            let f = (h - 180) as f64 / 60.0;
            (0, (255.0 * (1.0 - f)) as u8, 255)
        }
        240..=299 => {
            let f = (h - 240) as f64 / 60.0;
            ((f * 255.0) as u8, 0, 255)
        }
        _ => {
            let f = (h - 300) as f64 / 60.0;
            (255, 0, (255.0 * (1.0 - f)) as u8)
        }
    };
    Color::Rgb(r, g, b)
}

