use anyhow::Result;
use comfy_table::{presets::UTF8_FULL, Cell, Color, Table};
use sea_orm::EntityTrait;

use crate::{db, entity::session};

pub async fn run() -> Result<()> {
    let db = db::connect().await?;
    let sessions = session::Entity::find().all(&db).await?;

    if sessions.is_empty() {
        println!("No sessions found.");
        return Ok(());
    }

    let mut table = Table::new();
    table.load_preset(UTF8_FULL);
    table.set_header(["Session ID", "Last Prompt", "Agent", "User", "CWD", "Created", "Updated"]);

    for s in &sessions {
        table.add_row(vec![
            Cell::new(&s.session_id),
            Cell::new(truncate(&s.session_name, 50)),
            Cell::new(&s.agent_name).fg(agent_color(&s.agent_name)),
            Cell::new(&s.user),
            Cell::new(&s.cwd),
            Cell::new(s.created_at.format("%Y-%m-%d %H:%M").to_string()),
            Cell::new(s.updated_at.format("%Y-%m-%d %H:%M").to_string()),
        ]);
    }

    println!("{table}");
    Ok(())
}

fn agent_color(agent: &str) -> Color {
    let a = agent.to_lowercase();
    if a.contains("claude") {
        Color::Rgb { r: 215, g: 107, b: 55 }   // Anthropic orange
    } else if a.contains("copilot") || a.contains("github") {
        Color::Rgb { r: 130, g: 80, b: 255 }    // Copilot purple
    } else if a.contains("cursor") {
        Color::Rgb { r: 80, g: 140, b: 255 }    // Cursor blue
    } else if a.contains("gemini") {
        Color::Rgb { r: 66, g: 133, b: 244 }    // Google blue
    } else if a.contains("aider") {
        Color::Rgb { r: 0, g: 196, b: 126 }     // Aider green
    } else if a.contains("openai") || a.contains("chatgpt") || a.contains("codex") {
        Color::Rgb { r: 16, g: 163, b: 127 }    // OpenAI teal-green
    } else if a.contains("windsurf") || a.contains("codeium") {
        Color::Rgb { r: 0, g: 192, b: 163 }     // Windsurf teal
    } else if a.contains("amazon") || a.contains("q developer") {
        Color::Rgb { r: 255, g: 153, b: 0 }     // AWS orange
    } else {
        Color::White
    }
}

fn truncate(s: &str, max: usize) -> String {
    if s.chars().count() <= max {
        s.to_string()
    } else {
        format!("{}…", s.chars().take(max - 1).collect::<String>())
    }
}

