use anyhow::Result;
use comfy_table::{presets::UTF8_FULL, Table};
use sea_orm::EntityTrait;

use crate::{db, entity::session};

pub async fn run() -> Result<()> {
    let db = db::connect().await?;
    let sessions = session::Entity::find().all(&db).await?;

    if sessions.is_empty() {
        println!("No sessions found.");
        return Ok(());
    }

    let mut table = Table::new();
    table.load_preset(UTF8_FULL);
    table.set_header(["Session ID", "Last Prompt", "Agent", "User", "CWD", "Created", "Updated"]);

    for s in &sessions {
        table.add_row([
            s.session_id.as_str(),
            &truncate(&s.session_name, 50),
            s.agent_name.as_str(),
            s.user.as_str(),
            s.cwd.as_str(),
            &s.created_at.format("%Y-%m-%d %H:%M").to_string(),
            &s.updated_at.format("%Y-%m-%d %H:%M").to_string(),
        ]);
    }

    // Render the table first (so comfy-table calculates widths without ANSI codes),
    // then inject colors around agent names in the output string.
    println!("{}", colorize_agents(&table.to_string()));
    Ok(())
}

// Post-process the rendered table string, wrapping known agent names with ANSI
// 256-color codes. 256-color is supported by virtually every modern terminal,
// unlike 24-bit RGB which silently falls back to white on some terminals.
fn colorize_agents(s: &str) -> String {
    const AGENTS: &[(&str, u8)] = &[
        ("Claude Code", 214),  // orange
        ("Copilot",     99),   // purple
        ("Cursor",      33),   // blue
        ("Gemini",      75),   // Google blue
        ("Aider",       42),   // green
        ("ChatGPT",     35),   // OpenAI teal-green
        ("Windsurf",    44),   // teal
        ("Amazon Q",    208),  // AWS orange
    ];

    let mut out = s.to_string();
    for (name, code) in AGENTS {
        out = out.replace(name, &format!("\x1b[38;5;{code}m{name}\x1b[0m"));
    }
    out
}

fn truncate(s: &str, max: usize) -> String {
    if s.chars().count() <= max {
        s.to_string()
    } else {
        format!("{}…", s.chars().take(max - 1).collect::<String>())
    }
}

