use anyhow::{Context, Result};
use chrono::{DateTime, Utc};
use sea_orm::{sea_query::OnConflict, ActiveValue::Set, DatabaseConnection, EntityTrait};
use serde::Deserialize;
use serde_json::Value;
use std::process::Command;

use crate::{
    db,
    entity::{repository, session},
};

const BRANCH: &str = "entire/checkpoints/v1";

pub async fn run() -> Result<()> {
    let db = db::connect().await?;
    let repos = repository::Entity::find().all(&db).await?;

    if repos.is_empty() {
        println!("No repositories tracked. Run `gossamer init` first.");
        return Ok(());
    }

    let mut grand_total = 0usize;

    for repo in &repos {
        match index_repo(&db, &repo.directory, &repo.name).await {
            Ok(0) => println!("'{}': no {} branch found.", repo.name, BRANCH),
            Ok(n) => {
                println!("'{}': indexed {} session(s).", repo.name, n);
                grand_total += n;
            }
            Err(e) => eprintln!("'{}': error — {}", repo.name, e),
        }
    }

    println!("\n{} session(s) indexed.", grand_total);
    Ok(())
}

async fn index_repo(db: &DatabaseConnection, repo_dir: &str, _repo_name: &str) -> Result<usize> {
    // Bail early if the branch doesn't exist in this repo.
    let check = Command::new("git")
        .args(["rev-parse", "--verify", BRANCH])
        .current_dir(repo_dir)
        .output()
        .context("failed to run git")?;

    if !check.status.success() {
        return Ok(0);
    }

    // List every file tracked on the branch.
    let ls = Command::new("git")
        .args(["ls-tree", "-r", "--name-only", BRANCH])
        .current_dir(repo_dir)
        .output()
        .context("git ls-tree failed")?;

    let listing = String::from_utf8(ls.stdout)?;

    // Session metadata lives at XX/yyyyyyyyyy/N/metadata.json where N is all digits.
    let meta_paths: Vec<&str> = listing
        .lines()
        .filter(|l| {
            l.ends_with("/metadata.json")
                && l.matches('/').count() == 3
                && l.split('/').nth(2).map_or(false, |s| s.chars().all(|c| c.is_ascii_digit()))
        })
        .collect();

    let user = std::env::var("USER")
        .or_else(|_| std::env::var("USERNAME"))
        .unwrap_or_else(|_| "unknown".to_string());

    let mut count = 0;

    for meta_path in meta_paths {
        let jsonl_path = format!("{}full.jsonl", &meta_path[..meta_path.len() - "metadata.json".len()]);

        let meta_bytes = match git_show(repo_dir, meta_path) {
            Ok(b) => b,
            Err(e) => { eprintln!("  skipping {}: {}", meta_path, e); continue; }
        };
        let jsonl_bytes = match git_show(repo_dir, &jsonl_path) {
            Ok(b) => b,
            Err(_) => continue,
        };

        match parse_session(&meta_bytes, &jsonl_bytes, &user) {
            Ok(model) => {
                upsert_session(db, model).await?;
                count += 1;
            }
            Err(e) => eprintln!("  skipping {}: {}", meta_path, e),
        }
    }

    Ok(count)
}

fn git_show(repo_dir: &str, path: &str) -> Result<Vec<u8>> {
    let out = Command::new("git")
        .args(["show", &format!("{}:{}", BRANCH, path)])
        .current_dir(repo_dir)
        .output()
        .context("failed to run git show")?;

    if !out.status.success() {
        anyhow::bail!("object not found: {}", path);
    }
    Ok(out.stdout)
}

fn parse_session(meta_bytes: &[u8], jsonl_bytes: &[u8], user: &str) -> Result<session::ActiveModel> {
    let meta: SessionMetadata = serde_json::from_slice(meta_bytes)
        .context("failed to parse metadata.json")?;

    let created_at = meta
        .created_at
        .as_deref()
        .and_then(|s| DateTime::parse_from_rfc3339(s).ok())
        .map(|dt: DateTime<chrono::FixedOffset>| dt.with_timezone(&Utc))
        .unwrap_or_else(Utc::now);

    let session_name = meta
        .summary
        .and_then(|s| s.intent)
        .filter(|s| !s.is_empty())
        .unwrap_or_else(|| format!("session:{}", &meta.session_id[..8]));

    let agent_name = meta.agent.unwrap_or_else(|| "unknown".to_string());

    let mut latest: Option<DateTime<Utc>> = None;
    let mut cwd = String::new();
    let mut last_prompt: Option<String> = None;

    for line in jsonl_bytes.split(|&b| b == b'\n') {
        if line.is_empty() {
            continue;
        }
        let v: Value = match serde_json::from_slice(line) {
            Ok(v) => v,
            Err(_) => continue,
        };

        if let Some(ts) = v.get("timestamp").and_then(Value::as_str) {
            if let Ok(dt) = DateTime::parse_from_rfc3339(ts) {
                let dt: DateTime<Utc> = dt.with_timezone(&Utc);
                if latest.map_or(true, |l| dt > l) {
                    latest = Some(dt);
                }
            }
        }

        if cwd.is_empty() {
            if let Some(c) = v.get("cwd").and_then(Value::as_str) {
                cwd = c.to_string();
            }
        }

        if v.get("type").and_then(Value::as_str) == Some("user") {
            if let Some(Value::String(text)) = v.get("message").and_then(|m| m.get("content")) {
                let text = text.trim().to_string();
                if !text.is_empty() {
                    last_prompt = Some(text);
                }
            }
        }
    }

    let updated_at = latest.unwrap_or(created_at);
    let session_name = last_prompt.unwrap_or(session_name);

    Ok(session::ActiveModel {
        session_id: Set(meta.session_id),
        agent_name: Set(agent_name),
        user: Set(user.to_string()),
        created_at: Set(created_at),
        updated_at: Set(updated_at),
        cwd: Set(cwd),
        session_name: Set(session_name),
    })
}

async fn upsert_session(db: &DatabaseConnection, model: session::ActiveModel) -> Result<()> {
    session::Entity::insert(model)
        .on_conflict(
            OnConflict::column(session::Column::SessionId)
                .update_columns([
                    session::Column::AgentName,
                    session::Column::UpdatedAt,
                    session::Column::Cwd,
                    session::Column::SessionName,
                ])
                .to_owned(),
        )
        .exec(db)
        .await?;
    Ok(())
}

#[derive(Deserialize)]
struct SessionMetadata {
    session_id: String,
    agent: Option<String>,
    created_at: Option<String>,
    summary: Option<Summary>,
}

#[derive(Deserialize)]
struct Summary {
    intent: Option<String>,
}

use anyhow::{Context, Result};
use sea_orm::{ActiveValue::Set, ColumnTrait, EntityTrait, QueryFilter};
use std::{env, fs, io::Write, path::PathBuf, process::Command};

use crate::{db, entity::repository};

const HOOK_MARKER: &str = "# gossamer:";
const HOOK_SNIPPET: &str = r#"
# gossamer: re-index sessions after entireio checkpoints
if git log -1 --format="%B" | grep -q "Entire-Checkpoint:"; then
    gossamer index >/dev/null 2>&1 || true
fi"#;

pub async fn run() -> Result<()> {
    let cwd = env::current_dir().context("failed to get current directory")?;
    let cwd_str = cwd.to_string_lossy().to_string();

    let remote = git_remote(&cwd_str)?;
    let name = repo_name_from_remote(&remote);

    if entire_already_configured(&cwd_str) {
        println!("`entire` hooks already installed, skipping `entire configure`.");
    } else {
        println!("Running `entire configure`...");
        let status = Command::new("entire")
            .arg("configure")
            .status()
            .context("`entire configure` failed to launch — is entireio installed?")?;

        if !status.success() {
            anyhow::bail!("`entire configure` exited with status {}", status);
        }
    }

    install_post_commit_hook(&cwd_str)?;

    let db = db::connect().await?;

    let existing = repository::Entity::find()
        .filter(repository::Column::Directory.eq(&cwd_str))
        .one(&db)
        .await?;

    if existing.is_some() {
        println!("'{}' is already registered with gossamer.", name);
        return Ok(());
    }

    repository::Entity::insert(repository::ActiveModel {
        directory: Set(cwd_str.clone()),
        remote: Set(remote),
        name: Set(name.clone()),
        ..Default::default()
    })
    .exec(&db)
    .await
    .context("failed to register repository")?;

    println!("Initialized '{}' ({}).", name, cwd_str);
    Ok(())
}

/// Returns true if entireio has already written its hooks into this repo.
fn entire_already_configured(repo_dir: &str) -> bool {
    let git_dir = match git_common_dir(repo_dir) {
        Ok(d) => d,
        Err(_) => return false,
    };
    let post_commit = git_dir.join("hooks").join("post-commit");
    fs::read_to_string(post_commit)
        .map(|c| c.contains("entire hooks git"))
        .unwrap_or(false)
}

fn install_post_commit_hook(repo_dir: &str) -> Result<()> {
    let git_dir = git_common_dir(repo_dir)?;
    let hook_path = git_dir.join("hooks").join("post-commit");

    if hook_path.exists() {
        let content = fs::read_to_string(&hook_path)?;
        if content.contains(HOOK_MARKER) {
            println!("post-commit hook already contains gossamer indexing, skipping.");
            return Ok(());
        }
        let mut file = fs::OpenOptions::new().append(true).open(&hook_path)?;
        writeln!(file, "{}", HOOK_SNIPPET)?;
    } else {
        fs::create_dir_all(hook_path.parent().unwrap())?;
        fs::write(&hook_path, format!("#!/bin/sh\n{}\n", HOOK_SNIPPET))?;
    }

    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        let mut perms = fs::metadata(&hook_path)?.permissions();
        perms.set_mode(0o755);
        fs::set_permissions(&hook_path, perms)?;
    }

    println!("Installed post-commit hook at {}.", hook_path.display());
    Ok(())
}

fn git_common_dir(repo_dir: &str) -> Result<PathBuf> {
    let out = Command::new("git")
        .args(["rev-parse", "--git-common-dir"])
        .current_dir(repo_dir)
        .output()
        .context("failed to run git")?;

    if !out.status.success() {
        anyhow::bail!("could not locate .git directory");
    }

    let rel = PathBuf::from(String::from_utf8(out.stdout)?.trim().to_string());
    Ok(if rel.is_absolute() {
        rel
    } else {
        PathBuf::from(repo_dir).join(rel)
    })
}

fn git_remote(dir: &str) -> Result<String> {
    let out = Command::new("git")
        .args(["remote", "get-url", "origin"])
        .current_dir(dir)
        .output()
        .context("failed to run git")?;

    if !out.status.success() {
        anyhow::bail!("not a git repository or no 'origin' remote is configured");
    }

    Ok(String::from_utf8(out.stdout)?.trim().to_string())
}

fn repo_name_from_remote(remote: &str) -> String {
    remote
        .rsplit('/')
        .next()
        .unwrap_or(remote)
        .trim_end_matches(".git")
        .to_string()
}

use anyhow::Result;
use chrono::{DateTime, Utc};
use comfy_table::{presets::UTF8_FULL, Table};
use sea_orm::{EntityTrait, QueryOrder};

use crate::{db, entity::session};

pub async fn run() -> Result<()> {
    let db = db::connect().await?;
    let sessions = session::Entity::find()
        .order_by_desc(session::Column::UpdatedAt)
        .all(&db)
        .await?;

    if sessions.is_empty() {
        println!("No sessions found.");
        return Ok(());
    }

    let now = Utc::now();
    let mut table = Table::new();
    table.load_preset(UTF8_FULL);
    table.set_header(["", "Session ID", "Last Prompt", "Agent", "User", "CWD", "Created", "Updated"]);

    for s in &sessions {
        let age = (now - s.updated_at).num_seconds();
        let dot = if age < 3_600 { "● " } else if age < 86_400 { "● " } else { "" };

        table.add_row([
            dot,
            s.session_id.as_str(),
            &truncate(&s.session_name, 50),
            s.agent_name.as_str(),
            s.user.as_str(),
            s.cwd.as_str(),
            &relative_time(s.created_at),
            &relative_time(s.updated_at),
        ]);
    }

    println!("{}", colorize(&table.to_string(), &sessions, now));
    Ok(())
}

fn colorize(s: &str, sessions: &[session::Model], now: DateTime<Utc>) -> String {
    const AGENTS: &[(&str, u8)] = &[
        ("Claude Code", 214),
        ("Copilot",     99),
        ("Cursor",      33),
        ("Gemini",      75),
        ("Aider",       42),
        ("ChatGPT",     35),
        ("Windsurf",    44),
        ("Amazon Q",    208),
    ];

    let mut out = s.to_string();

    // Agent name colors
    for (name, code) in AGENTS {
        out = out.replace(name, &format!("\x1b[38;5;{code}m{name}\x1b[0m"));
    }

    // Activity dots — the dot is already in the rendered string for correct
    // column width; we just wrap it in the right ANSI color here.
    for session in sessions {
        let age = (now - session.updated_at).num_seconds();
        let (dot, code) = if age < 3_600 {
            ("● ", 82)   // green
        } else if age < 86_400 {
            ("● ", 214)  // amber
        } else {
            continue;
        };
        out = out.replacen(dot, &format!("\x1b[38;5;{code}m●\x1b[0m "), 1);
    }

    out
}

fn relative_time(dt: DateTime<Utc>) -> String {
    let secs = (Utc::now() - dt).num_seconds();
    match secs {
        s if s < 60 => "just now".to_string(),
        s if s < 3_600 => format!("{} min{} ago", s / 60, if s / 60 == 1 { "" } else { "s" }),
        s if s < 86_400 => format!("{} hr{} ago", s / 3_600, if s / 3_600 == 1 { "" } else { "s" }),
        s if s < 604_800 => format!("{} day{} ago", s / 86_400, if s / 86_400 == 1 { "" } else { "s" }),
        s if s < 2_592_000 => format!("{} wk{} ago", s / 604_800, if s / 604_800 == 1 { "" } else { "s" }),
        s if s < 31_536_000 => format!("{} mo ago", s / 2_592_000),
        s => format!("{} yr{} ago", s / 31_536_000, if s / 31_536_000 == 1 { "" } else { "s" }),
    }
}

fn truncate(s: &str, max: usize) -> String {
    if s.chars().count() <= max {
        s.to_string()
    } else {
        format!("{}…", s.chars().take(max - 1).collect::<String>())
    }
}

