use anyhow::Result;
use comfy_table::{presets::UTF8_HORIZONTAL_ONLY, Table};
use sea_orm::EntityTrait;
use std::env;

use crate::{db, entity::repository};

pub async fn run() -> Result<()> {
    let db = db::connect().await?;
    let repos = repository::Entity::find().all(&db).await?;

    if repos.is_empty() {
        println!("No repositories tracked. Run `gossamer init` in a git repo to get started.");
        return Ok(());
    }

    let cwd = env::current_dir().ok().map(|p| p.to_string_lossy().to_string());
    let current_repo = cwd.as_deref().and_then(|cwd| {
        repos.iter().find(|r| cwd.starts_with(r.directory.as_str()))
    });

    let mut table = Table::new();
    table.load_preset(UTF8_HORIZONTAL_ONLY);
    table.set_header(["", "Name", "Directory", "Remote"]);

    for repo in &repos {
        let marker = if current_repo.map_or(false, |r| r.directory == repo.directory) {
            "▶"
        } else {
            ""
        };
        table.add_row([marker, &repo.name, &repo.directory, &repo.remote]);
    }

    let rendered = table.to_string();
    println!("{}", colorize(&rendered, current_repo.map(|r| r.directory.as_str())));
    Ok(())
}

fn colorize(s: &str, current_dir: Option<&str>) -> String {
    let Some(dir) = current_dir else { return s.to_string() };
    // Color the marker and the directory of the current repo.
    s.replace("▶", "\x1b[38;5;82m▶\x1b[0m")
     .replace(dir, &format!("\x1b[38;5;82m{dir}\x1b[0m"))
}

